package gallery

const evidenceIndexHTML = `
<header class="max-w-3xl"><p class="text-sm font-medium text-accent">PRIVATE DESIGN REFERENCES</p><h1 class="mt-2 text-3xl font-semibold">Target evidence</h1><p class="mt-3 text-ink-muted">See what was recorded for a converted target and what still needs proof. These records preserve history; they do not certify a component.</p></header>
<nav aria-label="Private library" class="mt-5 flex flex-wrap gap-4 text-sm"><a href="{{.Originals}}" class="inline-flex min-h-11 items-center text-accent underline">Originals</a><a href="{{.Conversions}}" class="inline-flex min-h-11 items-center text-accent underline">Saved conversions</a><span aria-current="page" class="inline-flex min-h-11 items-center font-medium">Target evidence</span></nav>
<form action="/target-evidence" method="get" role="search" aria-label="Target evidence filters" class="mt-6 grid gap-4 border-y border-line py-5 sm:grid-cols-3">
{{if .Theme}}<input type="hidden" name="theme" value="{{.Theme}}">{{end}}<input type="hidden" name="limit" value="{{.Query.Limit}}">
<div class="min-w-0"><label for="evidence-subject" class="block text-sm font-medium">Exact capability ID</label><input id="evidence-subject" name="subject_id" value="{{.Query.SubjectID}}" class="mt-2 min-h-11 w-full rounded-md border border-line-strong bg-surface-raised p-2 text-ink focus-visible:outline-2 focus-visible:outline-focus"></div>
<div class="min-w-0"><label for="evidence-profile" class="block text-sm font-medium">Target profile</label><select id="evidence-profile" name="profile" class="mt-2 min-h-11 w-full rounded-md border border-line-strong bg-surface-raised p-2 text-ink focus-visible:outline-2 focus-visible:outline-focus"><option value="">All profiles</option><option value="static-web"{{if eq .Query.Profile "static-web"}} selected{{end}}>Static web</option><option value="go-web"{{if eq .Query.Profile "go-web"}} selected{{end}}>Go web</option><option value="react-web"{{if eq .Query.Profile "react-web"}} selected{{end}}>React web</option><option value="portable"{{if eq .Query.Profile "portable"}} selected{{end}}>Portable</option><option value="cli"{{if eq .Query.Profile "cli"}} selected{{end}}>CLI</option></select></div>
<div class="min-w-0"><label for="evidence-archive" class="block text-sm font-medium">Exact archive ID</label><input id="evidence-archive" name="archive_id" value="{{.Query.ArchiveID}}" class="mt-2 min-h-11 w-full rounded-md border border-line-strong bg-surface-raised p-2 text-ink focus-visible:outline-2 focus-visible:outline-focus"></div>
<div class="flex flex-wrap items-center gap-4 sm:col-span-3"><button class="min-h-11 rounded-md bg-accent px-4 py-2 font-medium text-accent-ink hover:bg-accent-hover focus-visible:outline-2 focus-visible:outline-focus focus-visible:outline-offset-2">Find evidence</button><a href="{{.Reset}}" class="inline-flex min-h-11 items-center text-accent underline">Reset filters</a></div></form>
<section class="mt-8" aria-labelledby="evidence-results"><h2 id="evidence-results" class="text-lg font-semibold">{{.Page.Total}} matching records</h2><p class="mt-2 max-w-3xl text-sm text-ink-muted">Recorded metadata only. Open a record to recheck retained bytes and original membership. Neither action checks today's transformer or authenticates the recorded claims.</p>
<div class="mt-4 border-t border-line">{{range .Rows}}<article class="grid min-w-0 gap-3 border-b border-line py-5 sm:grid-cols-3"><div class="min-w-0 sm:col-span-2"><h3 class="break-all font-semibold">{{.Entry.Recorded.Subject.ID}}</h3><p class="mt-2 text-sm">{{.Entry.Recorded.Subject.Profile}} · {{.Entry.Recorded.Subject.Variant}} · {{.Entry.Recorded.Mode}}</p><p class="mt-2 break-all font-mono text-xs text-ink-muted">{{.Entry.SourceMember}}</p><p class="mt-2 text-sm">{{len .Entry.Recorded.IncompleteGates}} incomplete recorded gates. <strong>Target compatibility not verified.</strong></p></div><div class="flex flex-wrap items-start gap-3 text-sm"><a href="{{.Detail}}" class="inline-flex min-h-11 items-center text-accent underline">Inspect evidence<span class="sr-only"> for {{.Entry.Recorded.Subject.ID}}</span></a><a href="{{.Original}}" class="inline-flex min-h-11 items-center text-accent underline">Open original<span class="sr-only"> {{.Entry.SourceMember}}</span></a></div></article>{{else}}<div class="py-8"><h3 class="font-semibold">No evidence records match</h3><p class="mt-3 max-w-3xl text-ink-muted">Browse originals or clear the filters. Saving evidence is a separate, explicit CLI action with reviewed input hashes. Browsing never runs a conversion or creates proof.</p><a href="{{.Reset}}" class="mt-3 inline-flex min-h-11 items-center text-accent underline">Clear filters</a></div>{{end}}</div>
{{if .Next}}<a href="{{.Next}}" class="mt-5 inline-flex min-h-11 items-center rounded-md border border-line-strong px-4 py-2 text-accent focus-visible:outline-2 focus-visible:outline-focus">Next page</a>{{end}}</section>
<details class="mt-8 text-sm"><summary class="min-h-11 cursor-pointer py-3">Index revision and evidence limits</summary><p class="mt-2 break-all font-mono text-xs">{{.Page.Revision}}</p><p class="mt-3 max-w-3xl text-ink-muted">Gallery, CLI and MCP share this index and these IDs. Even nine claimed passes do not establish certification. Records and licensed bytes remain private; maintain a separate backup.</p></details>
`

const evidenceDetailHTML = `
<a href="{{.Back}}" class="inline-flex min-h-11 items-center text-accent underline">← Target evidence</a>
<header class="mt-5 max-w-3xl"><p class="text-sm font-medium text-accent">RECORDED TARGET EVIDENCE</p><h1 class="mt-2 break-all text-3xl font-semibold">{{.Detail.Entry.Recorded.Subject.ID}}</h1><p class="mt-3">{{.Detail.Entry.Recorded.Subject.Profile}} · {{.Detail.Entry.Recorded.Subject.Variant}} · {{.Detail.Entry.Recorded.Mode}}</p><p class="mt-3 break-all font-mono text-sm">{{.Detail.Entry.SourceMember}}</p></header>
<section class="mt-6 border-y border-line py-5" aria-labelledby="evidence-boundary"><h2 id="evidence-boundary" class="text-lg font-semibold">Historical bytes match. Target compatibility not verified.</h2><p class="mt-3 max-w-3xl text-ink-muted">{{.Detail.Rechecked.MatchedArtifacts}} retained artifacts and original archive membership were checked for this request. Recorded gate claims are not independently authenticated. Current transformer replay, complete dependency closure, semantic quality and consumer acceptance remain separate checks.</p></section>
<nav aria-label="Evidence actions" class="mt-5 flex flex-wrap gap-4"><a href="{{.Original}}" class="inline-flex min-h-11 items-center text-accent underline">Open original reference</a><a href="{{.JSON}}" class="inline-flex min-h-11 items-center text-accent underline">Read complete metadata as JSON</a></nav>
<section class="mt-8 min-w-0" aria-labelledby="evidence-captures">
<h2 id="evidence-captures" class="text-xl font-semibold">Retained captures</h2>
<p class="mt-2 max-w-3xl text-sm text-ink-muted">These are historical screenshots, not live components. Capture names come from the recorded evidence; they do not independently prove viewport, input method or behavior. Gallery theme controls change only this page, not captured pixels.</p>
{{if .Images.Choices}}
<form action="{{.Images.Action}}#evidence-captures" method="get" aria-label="Compare retained captures" class="mt-5 grid min-w-0 gap-4 border-y border-line py-5 sm:grid-cols-2">
{{range $key, $values := .Images.Context}}{{range $values}}<input type="hidden" name="{{$key}}" value="{{.}}">{{end}}{{end}}
<div class="min-w-0"><label for="evidence-image" class="block text-sm font-medium">Capture</label><select id="evidence-image" name="image" class="mt-2 min-h-11 w-full min-w-0 rounded-md border border-line-strong bg-surface-raised p-2 text-ink focus-visible:outline-2 focus-visible:outline-focus">{{range .Images.Choices}}<option value="{{.ID}}"{{if eq .ID $.Images.Image}} selected{{end}}>{{.ID}}</option>{{end}}</select></div>
<div class="min-w-0"><label for="evidence-compare" class="block text-sm font-medium">Compare below (optional)</label><select id="evidence-compare" name="compare" class="mt-2 min-h-11 w-full min-w-0 rounded-md border border-line-strong bg-surface-raised p-2 text-ink focus-visible:outline-2 focus-visible:outline-focus"><option value="">No comparison</option>{{range .Images.Choices}}<option value="{{.ID}}"{{if eq .ID $.Images.Compare}} selected{{end}}>{{.ID}}</option>{{end}}</select></div>
<div class="sm:col-span-2"><button class="min-h-11 rounded-md bg-accent px-4 py-2 font-medium text-accent-ink hover:bg-accent-hover focus-visible:outline-2 focus-visible:outline-focus focus-visible:outline-offset-2">Show captures</button><p class="mt-2 text-sm text-ink-muted">{{len .Images.Choices}} recorded image slots. PNG only; unsupported or damaged captures remain unavailable.</p></div>
</form>
{{range .Images.Selected}}<figure class="mt-6 min-w-0 border-b border-line pb-6">
<figcaption class="mb-3 min-w-0"><p class="break-all font-mono text-sm font-semibold">{{.Evidence.ID}}</p><p class="mt-2 text-sm text-ink-muted">{{.Evidence.Bytes}} recorded bytes · historical evidence</p><p class="mt-2 break-all font-mono text-xs text-ink-muted">SHA-256 {{.Evidence.SHA256}}</p>{{if .Problem}}<p class="mt-2 max-w-3xl text-sm text-ink-muted">{{.Problem}}</p>{{else}}<p class="mt-2 text-sm text-ink-muted">{{.Width}} × {{.Height}} pixels</p><a href="{{.URL}}" class="mt-2 inline-flex min-h-11 items-center text-accent underline focus-visible:outline-2 focus-visible:outline-focus">Open full-size PNG<span class="sr-only"> {{.Evidence.ID}}</span></a>{{end}}</figcaption>
{{if not .Problem}}<img src="{{.URL}}" alt="Historical capture {{.Evidence.ID}}; inspect its original source and recorded claims separately" width="{{.Width}}" height="{{.Height}}" class="block h-auto max-w-full border border-line" loading="lazy">{{end}}
</figure>{{end}}
{{else}}<p class="mt-4 max-w-3xl text-sm text-ink-muted">No image slots were retained in this record. Its metadata is still useful; browsing does not import temporary screenshots or invent a visual preview.</p>{{end}}
</section>
<section class="mt-8" aria-labelledby="evidence-gates"><h2 id="evidence-gates" class="text-xl font-semibold">Nine recorded gates</h2><p class="mt-2 max-w-3xl text-sm text-ink-muted">Status below is the receipt author's claim. A scoped task check does not complete a broader gate.</p><dl class="mt-4 border-t border-line">{{range .Gates}}<div class="grid min-w-0 gap-3 border-b border-line py-5 sm:grid-cols-3"><dt class="font-semibold">{{.Name}}<span class="mt-2 block text-sm font-normal">Recorded: <code>{{.Result.Status}}</code></span></dt><dd class="min-w-0 sm:col-span-2"><p class="break-words">{{.Gate.Scope}}</p>{{if .Result.Reason}}<p class="mt-2 break-words text-sm text-ink-muted">{{.Result.Reason}}</p>{{end}}{{if not .Gate.Applicable}}<p class="mt-2 break-words text-sm">Declared exclusion: {{.Gate.Reason}}</p>{{end}}{{if .Gate.ReviewAssertion}}<p class="mt-2 break-words text-sm text-ink-muted">Review assertion, not authenticated: {{.Gate.ReviewAssertion}}</p>{{end}}<p class="mt-2 text-sm">{{len .Result.Evidence}} recorded evidence items; {{len .Gate.Slots}} declared slots.</p></dd></div>{{end}}</dl></section>
<details class="mt-8 text-sm"><summary class="min-h-11 cursor-pointer py-3">Exact identities and private access</summary><dl class="mt-4 grid min-w-0 gap-4"><div><dt>Evidence ID</dt><dd class="break-all font-mono text-xs">{{.Detail.Entry.ID}}</dd></div><div><dt>Contract SHA-256</dt><dd class="break-all font-mono text-xs">{{.Detail.Rechecked.ContractSHA256}}</dd></div><div><dt>Receipt SHA-256</dt><dd class="break-all font-mono text-xs">{{.Detail.Rechecked.ReceiptSHA256}}</dd></div><div><dt>Source revision</dt><dd class="break-all font-mono text-xs">{{.Detail.Rechecked.Subject.SourceRevision}}</dd></div><div><dt>Target artifact SHA-256</dt><dd class="break-all font-mono text-xs">{{.Detail.Rechecked.Subject.ArtifactSHA256}}</dd></div><div><dt>Index revision</dt><dd class="break-all font-mono text-xs">{{.Detail.Revision}}</dd></div></dl><p class="mt-4 max-w-3xl text-ink-muted">No evidence code or bundled asset is executed here. Retained archive membership is not a claim that this is the vendor's latest release. Original retrieval remains available independently when a record is damaged or unsuitable.</p></details>
`

const evidenceProblemHTML = `
<div class="max-w-3xl"><p class="text-sm font-medium text-accent">PRIVATE TARGET EVIDENCE</p><h1 class="mt-2 text-3xl font-semibold">{{.Title}}</h1><p class="mt-4 text-ink-muted">{{.Message}}</p><nav aria-label="Evidence recovery" class="mt-6 flex flex-wrap gap-4"><a href="{{.Back}}" class="inline-flex min-h-11 items-center text-accent underline">Return to target evidence</a>{{if .Original}}<a href="{{.Original}}" class="inline-flex min-h-11 items-center text-accent underline">Open original reference</a>{{end}}<a href="{{.Originals}}" class="inline-flex min-h-11 items-center text-accent underline">Browse original library</a></nav></div>
`
